(6979725, 1052929, 89723, '<td valign="top">Congratulations! I am a big fan of your work and appreciate that you share many of the ways you accomplish these incredible works. Look forward to seeing more in the future.</td>', 'Congratulations! I am a big fan of your work and appreciate that you share many of the ways you accomplish these incredible works. Look forward to seeing more in the future.', '2013-02-15 09:25:48.000000', NULL, 0),
(6979726, 1052926, 89723, '<td valign="top">Congratulations! This was my favorite of the challenge. Glad to see this on the frontpage. It really deserves to be there.</td>', 'Congratulations! This was my favorite of the challenge. Glad to see this on the frontpage. It really deserves to be there.', '2013-02-15 09:28:17.000000', NULL, 0),
(6979727, 1052936, 89723, '<td valign="top">COngratulations on 5th place. I really like this shot. Well thought out and executed.</td>', 'COngratulations on 5th place. I really like this shot. Well thought out and executed.', '2013-02-15 09:29:35.000000', NULL, 0),
(6979730, 1052923, 89723, '<td valign="top">Underrated! Your work is top notch. I''m a big fan and find myself searching out your entries. Keep em coming.</td>', 'Underrated! Your work is top notch. I''m a big fan and find myself searching out your entries. Keep em coming.', '2013-02-15 09:31:54.000000', NULL, 0),
